{"g":5,"b":2,"k":"h","q":"Hvad betyder 'What do you mean?'","o":["Hvad betyder det?","Hvad mener du?","Hvad hedder du?","Hvad vil du?"],"a":"Hvad mener du?","r":"'What do you mean?' = hvad mener du?"},
{"g":5,"b":2,"k":"h","q":"Hvad betyder 'It's not fair!'?","o":["Det er ikke retfærdigt!","Det er ikke pænt!","Det er ikke langt!","Det er ikke sjovt!"],"a":"Det er ikke retfærdigt!","r":"'Fair' betyder retfærdig."},
{"g":5,"b":2,"k":"h","q":"Hvad betyder 'That's a good point'?","o":["Det er et godt sted","Det er en god karakter","Det er en god blyant","Det er en god pointe"],"a":"Det er en god pointe","r":"'Point' betyder pointe eller argument."},
{"g":5,"b":2,"k":"h","q":"Hvad betyder 'I changed my mind'?","o":["Jeg har mistet hovedet","Jeg har glemt det","Jeg har skiftet mening","Jeg har lært det"],"a":"Jeg har skiftet mening","r":"'Change your mind' = skifte mening."},
{"g":5,"b":2,"k":"h","q":"Hvad betyder 'By the way'?","o":["Ved vejen","Forresten","På vej","Med det samme"],"a":"Forresten","r":"'By the way' bruges, når man vil sige noget nyt: forresten …"},
{"g":5,"b":2,"k":"h","q":"Hvad betyder 'Hang on a second'?","o":["Vent et øjeblik","Hæng den op","Hold fast i ét sekund","Om et sekund er det slut"],"a":"Vent et øjeblik","r":"'Hang on' betyder vent lidt."},
{"g":5,"b":2,"k":"h","q":"Hvad betyder 'Is it all right if I sit here?'","o":["Sidder jeg rigtigt her?","Er alt rigtigt her?","Må jeg sidde til højre?","Er det i orden, at jeg sidder her?"],"a":"Er det i orden, at jeg sidder her?","r":"'Is it all right if …?' = er det i orden, hvis …?"},
{"g":5,"b":2,"k":"h","q":"Hvad betyder 'Well done, you did it!'?","o":["Godt, du gjorde det færdigt i går!","Hvor er det godt lavet mad!","Godt gået, du klarede det!","Det var godt, du kom!"],"a":"Godt gået, du klarede det!","r":"'Well done' = godt gået, 'you did it' = du klarede det."},
